from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='El Cantar de mio Cid es la primera obra poética extensa de la literatura española y el único cantar épico castellano conservado casi completo. Este capítulo explica cómo ha llegado hasta nosotros, cómo se organiza su relato, qué forma métrica emplea y por qué su tono sobrio inaugura una tradición literaria.',
        quotes=[Q('es_cid','Se trata de la primera obra poética extensa','conservado casi completo'), Q('en_cid','is an anonymous 12th-century cantar de gesta','oldest preserved Castilian epic poem')]))
    P.append(dict(text='El poema se conserva en un único manuscrito, hoy en la Biblioteca Nacional de España, que forma parte de un códice del siglo XIV y está incompleto: faltan la primera hoja y otras dos del interior. El colofón menciona a Per Abbat y la fecha de 1207, pero esa fecha se refiere a la copia que sirvió de modelo y no demuestra que Per Abbat fuera el autor; la crítica actual sitúa la composición de la versión conservada hacia el año 1200. Conviene distinguir, por tanto, tres momentos: la historia del Cid real, que murió en 1099, la composición del poema, y la copia material del códice.',
        quotes=[Q('en_cid','The existing copy forms part of a 14th-century codex','missing the first page and two others in the middle.'), Q('es_cid','La versión conservada fue compuesta, según la mayoría de la crítica actual, alrededor del año 1200')]))
    P.append(dict(text='La cuestión de la autoría enfrenta a dos tradiciones críticas. Ramón Menéndez Pidal incluyó el Cantar en la tradición popular que llamó mester de juglaría: poemas transmitidos de generación en generación, que los juglares recitaban en público y modificaban según la ocasión. Los llamados individualistas, en cambio, atribuyen el poema a un autor concreto, culto y con formación jurídica. El propio texto conserva señales de oralidad: termina con una petición de vino para quien lo ha recitado, y su repertorio de frases hechas ayudaba al juglar a recordar o improvisar el verso.',
        quotes=[Q('en_cid','The Spanish medievalist Ramón Menéndez Pidal included','mester de juglaría.'), Q('es_cid','La tradición épica posee un recurso expresivo característico','la recitación o la improvisación')]))
    P.append(dict(text='Los editores dividen el poema en tres cantares desde la edición de Menéndez Pidal de 1913. La división podría reflejar las tres sesiones en que el autor consideraba conveniente que el juglar recitara la gesta, y el propio texto la señala con versos como «Aquí compieça la gesta de mio Çid el de Bivar» al comienzo del segundo cantar. El primero es el Cantar del destierro, el segundo el Cantar de las bodas de las hijas del Cid y el tercero el Cantar de la afrenta de Corpes. El manuscrito, sin embargo, es un texto seguido, sin separación entre cantares.',
        quotes=[Q('es_cid','Los editores del texto, desde la edición de Menéndez Pidal de 1913, lo han dividido en tres cantares.'), Q('en_cid','Since 1913, and following the work of Ramón Menéndez Pidal','divided into three parts')]))
    P.append(dict(text='Más allá de esa división externa, la estructura interna del poema gira en torno a la honra del héroe. El Cid pierde la honra con el destierro, la recupera al conquistar Valencia y obtener el perdón del rey, vuelve a perderla cuando los infantes de Carrión maltratan a sus hijas en el robledal de Corpes y la restaura, ya multiplicada, mediante el juicio en las Cortes y los nuevos matrimonios de sus hijas. Es una curva de pérdida y restauración en la que la segunda ascensión supera a la primera, de modo que el tema profundo es el ascenso social del infanzón que alcanza un señorío hereditario por su propio esfuerzo.',
        quotes=[Q('es_cid','El tema del Cantar de mio Cid es el complejo proceso de recuperación de la honra perdida por el héroe','de partida.'), Q('en_cid','To regain his honor, he participated in the battles against the Moorish armies and conquered Valencia.')]))
    P.append(dict(text='La forma métrica es singular. Los versos son anisosilábicos, aunque predominan los de catorce a dieciséis sílabas, y se dividen en dos hemistiquios separados por una cesura. No se agrupan en estrofas, sino en tiradas: series de longitud variable cuyos versos comparten una misma rima asonante. En la edición de Menéndez Pidal la longitud de las tiradas varía entre 3 y 190 versos y suele coincidir con una unidad de contenido. La asonancia, a diferencia de la rima consonante, atiende solo a las vocales desde la última sílaba tónica, y la «e» final no cuenta a efectos de rima.',
        quotes=[Q('es_cid','Sus versos no se agrupan en estrofas, sino en tiradas','misma rima asonante.'), Q('en_cid','It consists of more than 3,700 verses','The rhyme is assonant.')]))
    P.append(dict(text='El tono del Cantar es realista, algo poco habitual en la épica medieval europea. No hay magia: incluso la aparición del arcángel Gabriel ocurre en un sueño. El realismo y la sobriedad retórica son rasgos importantes porque, según la crítica, imprimen un sello definitorio a la literatura española posterior, desde La Celestina y la novela picaresca hasta el Quijote. El poema, además, se aparta a veces de la verdad histórica: no menciona a un hijo del Cid y las hijas, que en la realidad no se llamaban Elvira y Sol, no llegaron a ser reinas.',
        quotes=[Q('en_cid','Unlike other European medieval epics, the tone is realist.','happens in a dream.'), Q('es_cid','El realismo, y su asociada sobriedad en el empleo de la retórica, es importante','el Quijote...')]))
    P.append(dict(role='definition', text='Cantar de gesta: poema narrativo de tema heroico, compuesto para ser recitado en público por juglares, escrito en versos irregulares y de rima asonante, agrupados en tiradas en lugar de estrofas. El Cantar de mio Cid es el único ejemplar castellano conservado casi completo.',
        quotes=[Q('es_mester','El mester de juglaría era el más popular','de rima asonante en largas tiradas monorrimas'), Q('es_cid','el único cantar épico castellano conservado casi completo')]))
    P.append(dict(role='consejo', text='Al leer el Cantar, no busque un verso de medida fija: cuente primero los hemistiquios y atienda a la asonancia de cada tirada. Observará que el ritmo descansa en la cesura y en las fórmulas repetidas, no en un número rígido de sílabas.',
        quotes=[Q('es_cid','divididos en dos hemistiquios separados por cesura.'), Q('en_cid','each with a caesura between the hemistiches.')]))
    P.append(dict(role='self_check', text='¿Por qué la fecha de 1207 del colofón no basta para atribuir el poema a Per Abbat? ¿Qué diferencia hay entre una tirada y una estrofa? ¿Cómo se manifiestan en el texto la pérdida y la restauración de la honra del Cid?',
        quotes=[Q('en_cid','However, Per Abbad puts the date 1207 after his name','now lost.'), Q('es_cid','Esto invalida la teoría de Colin Smith de que el autor fue Per Abbat')]))
    return P

def problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='Según la numeración tradicional de versos del Cantar de mio Cid, el tercer cantar, el de la afrenta de Corpes, comprende los versos 2278 a 3730, y el poema completo llega hasta el verso 3730. Calcule cuántos versos tiene ese cantar y qué porcentaje del poema representa.',
        expected='38.95', quotes=[Q('es_cid','Tercer cantar. Cantar de la afrenta de Corpes (vv. 2278–3730)'), Q('en_cid','Cantar de la Afrenta de Corpes (verses 2278–3730)')],
        method='Contar versos de un intervalo cerrado y expresar la razón como porcentaje',
        solution=dict(given=[dict(symbol='v_i',value=2278,unit='dimensionless',meaning='primer verso del tercer cantar'),dict(symbol='v_f',value=3730,unit='dimensionless',meaning='último verso del poema'),dict(symbol='N',value=3730,unit='dimensionless',meaning='versos totales (numeración tradicional)')],
          unknown='El número de versos del tercer cantar y su porcentaje sobre el poema.',
          model=[dict(name='Versos de un intervalo cerrado',latex='n_3 = v_f - v_i + 1',symbolic='v_f - v_i + 1'),dict(name='Porcentaje',latex='p_3 = 100\\,\\frac{n_3}{N}',symbolic='100*n_3/N')],
          assumptions=['La numeración es la de la edición de Menéndez Pidal, que numera los versos de forma continua.'],
          development=['Un intervalo cerrado de versos incluye ambos extremos, por lo que se suma uno a la diferencia.'],
          steps=[dict(text='Versos del tercer cantar',equation='n_3 = 3730 - 2278 + 1',expression='3730-2278+1',expected=1453,unit='dimensionless'),
                 dict(text='Porcentaje del poema',equation='p_3 = 100 \\cdot 1453/3730',expression='100*1453/3730',expected=38.9544,unit='dimensionless')],
          result='El tercer cantar tiene 1453 versos, es decir, aproximadamente el 38,95 % del poema.',
          interpretation='El cantar más extenso es el último, el de la afrenta de Corpes, porque concentra el juicio y el reto.',
          limitations=['La numeración de los cantares varía ligeramente entre ediciones: algunas sitúan el final del primer cantar en el verso 1086, pero el tercero siempre va de 2278 a 3730.'],
          mistakes=['Olvidar sumar uno al restar los extremos de un intervalo cerrado.']))]
